local DoughHookMaker = {}
local PRODUCTS = {
    iron_dough_hook = { name = "Železni kavelj za testo", ironCost = 3, woodCost = 1, leatherCost = 1, time = 5, cost = 160, prestige = 3, happiness = 2, description = "Železni kavelj za mešanje testa." },
    bronze_dough_hook = { name = "Bronast kavelj za testo", bronzeCost = 3, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 390, prestige = 5, happiness = 3, description = "Bronast kavelj za pekarne." },
    silver_dough_hook = { name = "Srebrni kavelj za testo", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 940, prestige = 10, happiness = 4, description = "Srebrni kavelj za plemiške kuharje." },
    gilded_dough_hook = { name = "Pozlačeni kavelj za testo", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2030, prestige = 19, happiness = 5, description = "Pozlačeni kavelj za dvorne kuharje." },
    jewel_set_dough_hook = { name = "Draguljasti kavelj za testo", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 4380, prestige = 35, happiness = 7, description = "Draguljasti kavelj za kraljeve kuharje." },
    royal_sovereign_dough_hook = { name = "Kraljevski suvereni kavelj za testo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 9400, prestige = 67, happiness = 13, description = "Suvereni kavelj z biseri za krono." },
}
local BUILDINGS = {
    doughhook_workshop = { name = "Kavljeva delavnica", cost = { gold = 325, wood = 175, stone = 130, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    doughhook_house = { name = "Kavljeva hiša", cost = { gold = 1185, wood = 355, stone = 270, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_doughhook_atelier = { name = "Mojstrski kavljev atelje", cost = { gold = 2975, wood = 415, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_doughhook_palace = { name = "Suverena kavljeva palača", cost = { gold = 12920, wood = 635, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
DoughHookMaker.ironStock = 14; DoughHookMaker.bronzeStock = 12; DoughHookMaker.woodStock = 12; DoughHookMaker.leatherStock = 10; DoughHookMaker.silverStock = 8; DoughHookMaker.goldStock = 6; DoughHookMaker.jewelStock = 4; DoughHookMaker.pearlStock = 4
DoughHookMaker.productStock = {}; DoughHookMaker.buildings = {}; DoughHookMaker.maker = nil; DoughHookMaker.activeMaking = {}; DoughHookMaker.totalProducts = 0; DoughHookMaker.dayTimer = 0
function DoughHookMaker.init() DoughHookMaker.ironStock=14; DoughHookMaker.bronzeStock=12; DoughHookMaker.woodStock=12; DoughHookMaker.leatherStock=10; DoughHookMaker.silverStock=8; DoughHookMaker.goldStock=6; DoughHookMaker.jewelStock=4; DoughHookMaker.pearlStock=4; DoughHookMaker.productStock={}; DoughHookMaker.buildings={}; DoughHookMaker.maker=nil; DoughHookMaker.activeMaking={}; DoughHookMaker.totalProducts=0; DoughHookMaker.dayTimer=0; print("[DoughHookMaker] Royal Dough Hook Maker System initialized (6 products, 4 buildings)") end
function DoughHookMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DoughHookMaker.maker={name=n or ("Kavljist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kavljist najet: %s (spretnost: %d)",DoughHookMaker.maker.name,s),"success") end; return true end
function DoughHookMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DoughHookMaker.build(id) local ok,e=DoughHookMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DoughHookMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DoughHookMaker.getQualityBonus() local b=0; for _,bd in ipairs(DoughHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DoughHookMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and DoughHookMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and DoughHookMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and DoughHookMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and DoughHookMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and DoughHookMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DoughHookMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DoughHookMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and DoughHookMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #DoughHookMaker.buildings==0 then return false,"Potrebna kavljeva delavnica" end; if not DoughHookMaker.maker then return false,"Potreben kavljist" end; return true end
function DoughHookMaker.make(pt,qty) qty=qty or 1; local ok,e=DoughHookMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then DoughHookMaker.ironStock=DoughHookMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then DoughHookMaker.bronzeStock=DoughHookMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then DoughHookMaker.woodStock=DoughHookMaker.woodStock-d.woodCost*qty end; if d.leatherCost then DoughHookMaker.leatherStock=DoughHookMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then DoughHookMaker.silverStock=DoughHookMaker.silverStock-d.silverCost*qty end; if d.goldCost then DoughHookMaker.goldStock=DoughHookMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DoughHookMaker.jewelStock=DoughHookMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then DoughHookMaker.pearlStock=DoughHookMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if DoughHookMaker.maker then t=math.max(1,t-math.floor(DoughHookMaker.maker.skill/13)) end; table.insert(DoughHookMaker.activeMaking,{id="doughhook_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DoughHookMaker.completeMaking(m) local q=1.0+(DoughHookMaker.getQualityBonus()/100); if DoughHookMaker.maker then q=q+(DoughHookMaker.maker.skill/140) end; q=math.min(2.5,q); DoughHookMaker.productStock[m.productType]=(DoughHookMaker.productStock[m.productType] or 0)+m.quantity; DoughHookMaker.totalProducts=DoughHookMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DoughHookMaker.maker then DoughHookMaker.maker.itemsMade=DoughHookMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then DoughHookMaker.maker.skill=math.min(100,DoughHookMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kavelj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"doughhook.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function DoughHookMaker.update(dt) if not _G.state then return end; DoughHookMaker.dayTimer=DoughHookMaker.dayTimer+dt; if DoughHookMaker.dayTimer>=30 then DoughHookMaker.dayTimer=0; for i=#DoughHookMaker.activeMaking,1,-1 do local m=DoughHookMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DoughHookMaker.completeMaking(m); table.remove(DoughHookMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DoughHookMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DoughHookMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DoughHookMaker.getStats() return {ironStock=DoughHookMaker.ironStock,bronzeStock=DoughHookMaker.bronzeStock,woodStock=DoughHookMaker.woodStock,leatherStock=DoughHookMaker.leatherStock,silverStock=DoughHookMaker.silverStock,goldStock=DoughHookMaker.goldStock,jewelStock=DoughHookMaker.jewelStock,pearlStock=DoughHookMaker.pearlStock,productStock=DoughHookMaker.productStock,numBuildings=#DoughHookMaker.buildings,hasMaker=DoughHookMaker.maker~=nil,makerName=DoughHookMaker.maker and DoughHookMaker.maker.name or "—",makerSkill=DoughHookMaker.maker and DoughHookMaker.maker.skill or 0,activeMaking=#DoughHookMaker.activeMaking,totalProducts=DoughHookMaker.totalProducts} end
return DoughHookMaker
